"""Controller controller -- generated by plugin_authoring. See context.md for this plugin's iteration history."""

from __future__ import annotations

import json
import os
import threading
import udi_interface

LOGGER = udi_interface.LOGGER


class Controller(udi_interface.Node):
    id = 'controller'
    drivers = [{'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Status'}]
    def __init__(self, polyglot, primary='ctl', address='ctl', name='Rain Bird Controller'):
        super().__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.persist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "persist")
        os.makedirs(self.persist_dir, exist_ok=True)
        # Synchronization for __start()'s wait-for-configDone gate (see __configDoneHandler).
        self.configDone = threading.Condition()
        self.configDoneAlready = False
        self.poly.setCustomParamsDoc('<h2>Rain Bird plugin configuration</h2>\n<p>This plugin talks <b>directly</b> to your Rain Bird WiFi module (LNK) over your home network. No Rain Bird cloud account is used. There are only two settings: <b>host</b> and <b>password</b>. There is no user name or email.</p>\n\n<h3>host</h3>\n<p>The IP address of the Rain Bird WiFi module, for example <code>192.168.1.50</code>.</p>\n<ul>\n  <li>Find it in your router\'s list of connected devices (look for a device named like <i>Rain Bird</i> or <i>LNK</i>).</li>\n  <li><b>Strongly recommended:</b> give the module a DHCP reservation (fixed address) in your router so the address never changes.</li>\n  <li>Enter just the address - no <code>http://</code> and no trailing slash.</li>\n</ul>\n\n<h3>password</h3>\n<p>The password you set for the controller in the Rain Bird app when you added it. It is the same password the app uses to talk to the controller locally.</p>\n<p><b>Careful:</b> some Rain Bird modules lock out local access for 15 minutes after 3 wrong passwords. To avoid that, this plugin stops polling after repeated password-type failures and shows a notice instead of retrying. Fix the password and save to try again.</p>\n\n<h3>Zone names</h3>\n<p>Use the <b>Zone names</b> list (below the fields above) to give each zone a friendly name, for example zone <code>1</code> = <code>Front Lawn</code>. Zones you do not list are called "Zone 1", "Zone 2", and so on. Renaming takes effect on the existing nodes right away.</p>\n\n<h3>Good to know</h3>\n<ul>\n  <li>The controller can only talk to <b>one app at a time</b>. If you open the Rain Bird app while watering is being controlled here you may see a brief "busy" message in the plugin log; the plugin retries automatically.</li>\n  <li>Zone status is checked every 30 seconds; rain delay, rain sensor and water budget every 5 minutes.</li>\n  <li>Water budget is shown for information only; change it in the Rain Bird app.</li>\n  <li>If the controller drops off the network now and then, try putting the WiFi module on a dedicated 2.4 GHz-only network.</li>\n</ul>')
        self.CustomTypedParams = udi_interface.Custom(self.poly, 'customtypedparams')
        self.CustomTypedData = udi_interface.Custom(self.poly, 'customtypeddata')
        self.CustomTypedParams.load([{'name': 'zone_names', 'title': 'Zone names', 'desc': 'Optional friendly names for your sprinkler zones. Add one row per zone you want to name.', 'isList': True, 'params': [{'name': 'zone', 'title': 'Zone number', 'type': 'NUMBER', 'isRequired': True, 'desc': 'The station number on the controller (1, 2, 3 ...).'}, {'name': 'name', 'title': 'Zone name', 'type': 'STRING', 'isRequired': True, 'desc': 'What you want this zone to be called, e.g. Front Lawn.'}]}], True)
        # Additional node classes (rainbird_nodes) -- construct and self.poly.addNode() them from discover()/start() once their real addresses/names are known (run candidate names/addresses through self.poly.getValidName()/getValidAddress() first).
        self.poly.subscribe(self.poly.START, self.__start, address)
        self.poly.subscribe(self.poly.STOP, self.__stop)
        self.poly.subscribe(self.poly.POLL, self.__poll)
        self.poly.subscribe(self.poly.CONFIG, self.__configHandler)
        self.poly.subscribe(self.poly.CONFIGDONE, self.__configDoneHandler)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.parameterHandler)
        self.poly.subscribe(self.poly.CUSTOMNS, self.__customNSHandler)
        self.poly.subscribe(self.poly.CUSTOMDATA, self.__customDataHandler)
        self.poly.subscribe(self.poly.CUSTOMTYPEDDATA, self.customTypedDataHandler)
        self.poly.subscribe(self.poly.ADDNODEDONE, self.__addNodeDoneHandler)
        self.poly.subscribe(self.poly.DELNODEDONE, self.__removeNodeDoneHandler)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)
        self.poly.subscribe(self.poly.BONJOUR, self.__bonjourHandler)
        self.poly.addNode(self, conn_status='ST')

    def __start(self):
        LOGGER.info("%s: start", self.name)
        try:
            if not self.configDoneAlready:
                with self.configDone:
                    if not self.configDone.wait(timeout=10):
                        LOGGER.error("%s: timed out waiting for configDone", self.name)
                        return
            self.start()
        except Exception as ex:
            LOGGER.error("%s: start failed: %s", self.name, ex)

    def __stop(self):
        LOGGER.info("%s: stop", self.name)
        self.stop()

    def __poll(self, polltype):
        if polltype == "shortPoll":
            self.shortPoll()
        elif polltype == "longPoll":
            self.longPoll()

    def __configHandler(self, config):
        self.processConfig(config)

    def __configDoneHandler(self):
        LOGGER.info("%s: config done", self.name)
        with self.configDone:
            self.configDoneAlready = True
            self.configDone.notifyAll()

    def __addNodeDoneHandler(self, data):
        LOGGER.debug("%s: add node done: %s", self.name, data)

    def __removeNodeDoneHandler(self, data):
        LOGGER.debug("%s: remove node done: %s", self.name, data)

    def __customNSHandler(self, key, data):
        self.customParamHandler(key, data)

    def __customDataHandler(self, data):
        LOGGER.debug("%s: custom data: %s", self.name, data)

    def __bonjourHandler(self, response):
        LOGGER.debug("%s: bonjour: %s", self.name, response)

    # --- developer-authored overrides (edit freely; regeneration preserves them) ---

    def start(self):
        import rainbird_nodes as rb
        rb.LOGGER.info('Rain Bird plugin starting')
        rb.cleanup_foreign(self.poly, self)
        rb._S['started'] = True
        rb.bootstrap(self.poly, self.address)

    def stop(self):
        import rainbird_nodes as rb
        rb.LOGGER.info('Rain Bird plugin stopping')
        rb._S['started'] = False
        rb.shutdown()

    def discover(self, *args, **kwargs):
        import rainbird_nodes as rb
        rb.bootstrap(self.poly, self.address)

    def shortPoll(self, *args, **kwargs):
        import rainbird_nodes as rb
        rb.poll_fast(self.poly, self.address)

    def longPoll(self, *args, **kwargs):
        import rainbird_nodes as rb
        rb.poll_slow(self.poly, self.address)

    def processConfig(self, *args, **kwargs):
        pass

    def parameterHandler(self, params):
        import threading
        import rainbird_nodes as rb
        params = params or {}
        host = str(params.get('host') or '').strip()
        password = str(params.get('password') or '')
        changed = rb.configure(self.poly, host, password)
        if changed and rb._S['started'] and host and password:
            threading.Thread(target=rb.bootstrap, args=(self.poly, self.address), daemon=True).start()

    def customParamHandler(self, *args, **kwargs):
        pass

    def customTypedDataHandler(self, custom_params):
        import rainbird_nodes as rb
        self.CustomTypedData.load(custom_params)
        rb.set_zone_names(self.poly, custom_params)

    # --- command dispatch (profile cmds.accepts; see udi_interface.Node.runCmd) ---
    commands = {'DISCOVER': discover}
